+
+/** A condition accepted by conditional option helpers. */
+export type OptionCondition =
+  | string
+  | OptionDependencyCondition
+  | Pick<OptionDependencies, "anyOf" | "allOf">;
+
+function conditionDependencies(
+  condition: OptionCondition | OptionDependencies,
+  required: boolean | undefined,
+): OptionDependencies {
+  const normalized = typeof condition === "string"
+    ? { option: condition }
+    : condition;
+  return { ...normalized, ...(required === undefined ? {} : { required }) };
+}
+
+function conditionalOptionWithRequired<M extends Mode, T>(
+  condition: OptionCondition | OptionDependencies,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser: ValueParser<M, T> | undefined,
+  required: boolean | undefined,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  const names = Array.isArray(flagSpec) ? flagSpec : [flagSpec];
+  const options: OptionOptions = {
+    dependsOn: conditionDependencies(condition, required),
+  };
+  return valueParser == null
+    ? option(...names, options) as Parser<
+      M,
+      T | boolean,
+      ValueParserResult<T | boolean> | undefined
+    >
+    : option(...names, valueParser, options);
+}
+
+/** Creates an option which is required when its condition is unsatisfied. */
+export function requiredWhen<M extends Mode, T>(
+  condition: OptionCondition | OptionDependencies,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOptionWithRequired(condition, flagSpec, valueParser, true);
+}
+
+/** Creates an option which is hidden when its condition is unsatisfied. */
+export function optionalWhen<M extends Mode, T>(
+  condition: OptionCondition | OptionDependencies,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOptionWithRequired(condition, flagSpec, valueParser, false);
+}
+
+/** Creates an option with conditional dependency configuration. */
+export function conditionalOption<M extends Mode, T>(
+  condition: OptionCondition | OptionDependencies,
+  flagSpec: OptionName | readonly OptionName[],
+  valueParser?: ValueParser<M, T>,
+): Parser<M, T | boolean, ValueParserResult<T | boolean> | undefined> {
+  return conditionalOptionWithRequired(condition, flagSpec, valueParser, undefined);
+}
