+
+function findOptionTerm(usage: Usage): Extract<UsageTerm, { type: "option" }> | undefined {
+  for (const term of usage) {
+    if (term.type === "option") return term;
+    if (term.type === "optional" || term.type === "multiple") {
+      const found = findOptionTerm(term.terms);
+      if (found) return found;
+    } else if (term.type === "exclusive") {
+      for (const terms of term.terms) {
+        const found = findOptionTerm(terms);
+        if (found) return found;
+      }
+    }
+  }
+  return undefined;
+}
+
+function resolveOptionDependency(
+  usage: Usage,
+  parserPairs: readonly [string | symbol, Parser<Mode, unknown, unknown>][],
+): ResolvedOptionDependency | undefined {
+  const optionTerm = findOptionTerm(usage);
+  const condition = optionTerm?.dependsOn;
+  if (!condition) return undefined;
+  const key = parserPairs.find(([field, parser]) =>
+    field === condition.option || findOptionTerm(parser.usage)?.names.includes(condition.option as never)
+  )?.[0];
+  return key === undefined ? undefined : {
+    key,
+    condition,
+    dependeeName: findOptionTerm(
+      parserPairs.find(([field]) => field === key)![1].usage,
+    )?.names[0] ?? String(key),
+  };
+}
+
+function dependencyConditionsSatisfied(
+  condition: NonNullable<Extract<UsageTerm, { type: "option" }>["dependsOn"]>,
+  getValue: (option: string) => { readonly exists: boolean; readonly value: unknown },
+): boolean {
+  const isSatisfied = (item: { readonly option: string; readonly value?: unknown }) => {
+    const resolved = getValue(item.option);
+    return resolved.exists && ("value" in item
+      ? resolved.value === item.value
+      : Boolean(resolved.value));
+  };
+  if (condition.anyOf && !condition.anyOf.some(isSatisfied)) return false;
+  if (condition.allOf && !condition.allOf.every(isSatisfied)) return false;
+  return condition.option === undefined || isSatisfied(condition as { readonly option: string; readonly value?: unknown });
+}
