+  optionalWhen,
+  requiredWhen,
+} from "./primitives.ts";
+import { choice, string } from "./valueparser.ts";
+import { formatMessage } from "./message.ts";
+import assert from "node:assert/strict";
+import { describe, it } from "node:test";
+
+describe("conditional option dependencies", () => {
+  it("resolves object keys and flags through wrappers", () => {
+    const parser = object({
+      mode: withDefault(option("--mode", choice(["dev", "prod"])), "dev"),
+      config: conditionalOption({ option: "--mode", value: "prod" }, "--config", string()),
+    });
+
+    assert.deepEqual(parseSync(parser, ["--config", "x"]), {
+      success: true,
+      value: { mode: "dev", config: "x" },
+    });
+    assert.deepEqual(parseSync(parser, ["--mode", "prod", "--config", "x"]), {
+      success: true,
+      value: { mode: "prod", config: "x" },
+    });
+  });
+
+  it("validates required dependencies with the referenced flag and value", () => {
+    const parser = object({
+      mode: option("--mode", choice(["dev", "prod"])),
+      config: requiredWhen({ option: "mode", value: "prod" }, "--config", string()),
+    });
+    const result = parseSync(parser, ["--mode", "dev", "--config", "x"]);
+    assert.ok(!result.success);
+    if (!result.success) {
+      const error = formatMessage(result.error);
+      assert.ok(error.includes("requires option"));
+      assert.ok(error.includes("--mode"));
+      assert.ok(error.includes('"prod"'));
+    }
+  });
+
+  it("supports compound dependencies and empty compound semantics", () => {
+    const parser = object({
+      first: option("--first"),
+      second: option("--second"),
+      value: requiredWhen({ anyOf: [{ option: "first" }, { option: "second" }] }, "--value", string()),
+      all: requiredWhen({ allOf: [] }, "--all"),
+      never: requiredWhen({ anyOf: [] }, "--never"),
+    });
+    assert.ok(parseSync(parser, ["--first", "--value", "x", "--all"]).success);
+    assert.ok(!parseSync(parser, ["--first", "--value", "x", "--never"]).success);
+  });
+
+  it("hides unsatisfied optional conditions from suggestions and docs", () => {
+    const parser = object({
+      enabled: option("--enabled"),
+      secret: optionalWhen("enabled", "--secret", string()),
+    });
+    const suggestions = [...parser.suggest({
+      buffer: [], optionsTerminated: false, state: parser.initialState, usage: parser.usage,
+    }, "")];
+    assert.ok(!suggestions.some((suggestion) => suggestion.value === "--secret"));
+    const docs = parser.getDocFragments({ kind: "available", state: parser.initialState });
+    assert.ok(!docs.fragments.some((fragment) =>
+      fragment.type === "section" && fragment.entries.some((entry) =>
+        entry.term.type === "option" && entry.term.names.includes("--secret")
+      )
+    ));
+  });
+
+  it("rejects a dependent option when its explicitly false dependee is supplied", () => {
+    const parser = object({
+      enabled: option("--enabled", choice(["true", "false"])),
+      secret: optionalWhen("enabled", "--secret", string()),
+    });
+    assert.ok(!parseSync(parser, ["--enabled", "false", "--secret", "x"]).success);
+  });
+});
